@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AppSelectorScreen(
    onBackPressed: () -> Unit,
    viewModel: AppSelectorViewModel = viewModel()
) {
    val uiState = viewModel.uiState
    val scrollBehavior = TopAppBarDefaults.enterAlwaysScrollBehavior()

    Scaffold(
        modifier = Modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
        topBar = {
            TopAppBar(
                scrollBehavior = scrollBehavior,
                title = { Text("Select Apps") },
                navigationIcon = {
                    IconButton(onClick = onBackPressed) {
                        Icon(Icons.Default.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    if (!uiState.isLoading) {
                        IconButton(onClick = { viewModel.retryLoadApps() }) {
                            Icon(Icons.Default.Refresh, contentDescription = "Refresh")
                        }
                    }
                }
            )
        }
    ) { paddingValues ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            when {
                uiState.isLoading -> {
                    LoadingContent()
                }

                uiState.error != null -> {
                    ErrorContent(
                        error = uiState.error,
                        onRetry = { viewModel.retryLoadApps() }
                    )
                }

                else -> {
                    AppListContent(
                        supportedApps = uiState.supportedApps,
                        otherApps = uiState.otherApps,
                        selectedApps = uiState.selectedApps,
                        onAppToggle = viewModel::toggleAppSelection
                    )
                }
            }
        }
    }
}

@Composable
fun LoadingContent() {
    Box(
